SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, MAX(l.value) AS max_sbp, COUNT(DISTINCT CASE WHEN d.icd_code = '641.91' THEN l.subject_id END)::FLOAT / NULLIF(COUNT(l.subject_id), 0) AS stroke_rate, SUM(CASE WHEN l.value < 130 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(l.subject_id), 0) AS sbp_lt_130, SUM(CASE WHEN l.value BETWEEN 130 AND 139 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(l.subject_id), 0) AS sbp_130_139, SUM(CASE WHEN l.value BETWEEN 140 AND 159 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(l.subject_id), 0) AS sbp_140_159, SUM(CASE WHEN l.value >= 160 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(l.subject_id), 0) AS sbp_ge_160 FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN chartevents c ON i.stay_id = c.stay_id AND c.itemid = 57027 JOIN labevents l ON c.subject_id = l.subject_id AND c.charttime = l.charttime JOIN diagnoses_icd d ON l.subject_id = d.subject_id AND l.hadm_id = d.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 70 AND 80 AND c.value_uom = 'mmHg' AND l.value_uom = 'mmHg' AND (c.starttime - l.charttime) <= 24 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group;